#ifndef MOCK_DSP_DEPENDENCIES_H
#define MOCK_DSP_DEPENDENCIES_H

#include <stdbool.h>
#include <stddef.h>

/** Recorded interaction state for the hand-written DSP test doubles. */
typedef struct
{
    unsigned detector_process_calls;
    unsigned shifter_set_ratio_calls;
    unsigned shifter_process_calls;
    size_t detector_last_sample_count;
    size_t shifter_last_sample_count;
    float shifter_last_ratio;
} MockDspInteractions;

/** Reset all mock return values and call counters to successful defaults. */
void MockDsp_Reset(void);

/** Configure the pitch detector result returned by the next/all calls. */
void MockDsp_SetDetectorResult(bool valid, float pitch_hz, float confidence);

/** Configure whether the mocked PitchShifter_SetRatio succeeds. */
void MockDsp_SetShifterRatioResult(bool success);

/** Configure whether the mocked PitchShifter_ProcessBlock succeeds. */
void MockDsp_SetShifterProcessResult(bool success);

/** Read the accumulated mock interaction counters/arguments. */
MockDspInteractions MockDsp_GetInteractions(void);

#endif
